public final class User {
    private final String id;
    private final String email;
    private final String phone;
    private final String displayName;
    private final boolean marketingOptIn;

    private User(Builder b) {
        this.id = b.id;
        this.email = b.email;
        this.phone = b.phone;
        this.displayName = b.displayName;
        this.marketingOptIn = b.marketingOptIn;
    }

    public static final class Builder {
        private final String id;      // required
        private final String email;   // required
        private String phone;
        private String displayName;
        private boolean marketingOptIn;

        public Builder(String id, String email) {
            if (id == null || id.isBlank()) throw new IllegalArgumentException("id required");
            if (email == null || !email.contains("@")) throw new IllegalArgumentException("valid email required");
            this.id = id;
            this.email = email;
        }

        public Builder withPhone(String phone) {
            this.phone = phone;
            return this;
        }

        public Builder withDisplayName(String name) {
            this.displayName = name;
            return this;
        }

        public Builder withMarketingOptIn(boolean optIn) {
            this.marketingOptIn = optIn;
            return this;
        }

        public User build() {
            if (marketingOptIn && (phone == null && displayName == null)) {
                throw new IllegalStateException("marketing opt-in needs a contact channel");
            }
            return new User(this);
        }
    }
}

interface ReportBuilder {
    void reset();
    void addHeader(String title);
    void addSection(String body);
    void addFooter(String disclaimer);
    Report getReport();
}

final class ReportDirector {
    void buildSummary(ReportBuilder b, String title, List<String> highlights) {
        b.reset();
        b.addHeader(title);
        for (String h : highlights) b.addSection(h);
        b.addFooter("auto-generated");
    }

    void buildEmpty(ReportBuilder b, String title) {
        b.reset();
        b.addHeader(title);
        b.addFooter("no data");
    }
}
